import{_ as o,r as a,o as p,c as l,e as n,a as c,s as r}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"本地化 - October CMS - 3.x","titleTemplate":false,"description":"了解如何在 CMS 主题中翻译消息。","frontmatter":{"subtitle":"了解如何在 CMS 主题中翻译消息。"},"headers":[{"level":3,"title":"本地化文件结构","slug":"本地化文件结构","link":"#本地化文件结构","children":[{"level":4,"title":"参见","slug":"参见","link":"#参见","children":[]}]}],"relativePath":"3.x/zh-cn/cms/themes/localization.md","filePath":"3.x/zh-cn/cms/themes/localization.md"}'),i={name:"3.x/zh-cn/cms/themes/localization.md"};function m(d,s,u,g,h,k){const e=a("pre-heading"),t=a("post-heading");return p(),l("div",null,[n(e),s[0]||(s[0]=c("h1",null,"本地化",-1)),n(t),s[1]||(s[1]=r(`<div class="custom-block aside"><p>查看<a href="./../resources/multisite.html">多站点文章</a>以了解如何为您的网站设置活动语言。</p></div><p>主题可以通过放置在主题目录的 <strong>lang</strong> 子目录中的文件来提供本地化键。这些本地化键会自动注册，可以在主题内容中使用，也可以作为后端表单标签使用，类似于<a href="./../../extend/system/localization.html">插件本地化</a>。</p><h3 id="本地化文件结构"><a href="#本地化文件结构" class="header-anchor">#</a> 本地化文件结构</h3><p>以下是主题 <strong>lang</strong> 目录的示例。</p><pre class="dir-container"><code><p>├── themes
|   └── website
|       └── <code>lang</code>  <em>← 本地化目录</em>
|           ├── en.json  <em>← 本地化文件</em>
|           └── fr.json  <em>← 本地化文件</em></p>
</code></pre><p>本地化文件是一个 JSON 文件，其中字符串使用&quot;默认&quot;翻译的字符串作为键。例如，如果您的应用程序有法语翻译，您应该创建一个 <code>lang/fr.json</code> 文件。</p><div class="language-json extra-class"><pre class="language-json"><code><span class="token punctuation">{</span>
    <span class="token property">&quot;I love programming.&quot;</span><span class="token operator">:</span> <span class="token string">&quot;j&#39;adore programmer&quot;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>您还可以通过在 JSON 文件中使用完整的语言键来定义基于代码的键，例如，可以为 <strong>acme</strong> 主题使用 <code>theme.options.website_name</code>。</p><div class="language-json extra-class"><pre class="language-json"><code><span class="token punctuation">{</span>
    <span class="token property">&quot;theme.options.website_name&quot;</span><span class="token operator">:</span> <span class="token string">&quot;October CMS&quot;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>可以在主题文件中使用 <code>trans</code> Twig 过滤器来访问语言字符串。</p><div class="custom-block tip"><p>查看<a href="./../../markup/filter/trans.html">标记指南</a>以了解更多关于 Twig 中翻译的内容。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token comment">&lt;!-- j&#39;adore programmer --&gt;</span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>I love programming.<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>trans <span class="token delimiter punctuation">}}</span></span>

<span class="token comment">&lt;!-- October CMS --&gt;</span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>theme.options.website_name<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>trans <span class="token delimiter punctuation">}}</span></span>
</code></pre></div></div><h4 id="参见"><a href="#参见" class="header-anchor">#</a> 参见</h4><div class="custom-block also"><ul><li><a href="./../resources/multisite.html">多站点</a></li><li><a href="./../../extend/system/localization.html">插件本地化</a></li></ul></div>`,13))])}const v=o(i,[["render",m]]);export{f as __pageData,v as default};
